/*
 * Pinout (STM32F746G-DISCO)
 *
 * Header | MCU  | Peripheral
 * -------+------+------------------------------------------
 * A1     | PF10 | SW1 - increment digit (input, pull-up)
 * A2     | PF9  | SW2 - next operator (input, pull-up)
 * A3     | PF8  | SW3 - compute answer (input, pull-up)
 * A4     | PF7  | SW4 - next / confirm (input, pull-up)
 * B1     | PI11 | On-board user button - save / recall memory (input)
 * D2     | PG6  | 7-segment segment A (output)
 * D3     | PB4  | 7-segment segment B (output)
 * D4     | PG7  | 7-segment segment C (output)
 * D5     | PI0  | 7-segment segment D (output)
 * D6     | PH6  | 7-segment segment E (output)
 * D7     | PI3  | 7-segment segment F (output)
 * D8     | PI2  | 7-segment segment G (output)
 * D10    | PA8  | 7-segment digit 1 select (output)
 * D11    | PB15 | 7-segment digit 2 select (output)
 * D12    | PB14 | 7-segment digit 3 select (output)
 * D13    | PI1  | 7-segment digit 4 select (output)
 */

#include <stdint.h>
#include "stm32f7xx.h"

#if !defined(__SOFT_FP__) && defined(__ARM_FP)
  #warning "FPU is not initialized, but the project is compiling for an FPU. Please initialize the FPU before use."
#endif

void initializePins();
int translateCharacter(char);
void flashSegment(char);
void flashDisplay(char*);
void simple_delay(uint32_t count);


/* ---------------------------------------------------------------------------
 * FSM definitions
 * ------------------------------------------------------------------------- */

typedef enum {
    STATE_INIT,
    STATE_SELECT_OPERAND1,
    STATE_SELECT_OPERAND2,
    STATE_DIGIT1,
    STATE_DIGIT1_INC,
    STATE_DIGIT2,
    STATE_DIGIT2_INC,
    STATE_DIGIT3,
    STATE_DIGIT3_INC,
    STATE_DIGIT4,
    STATE_DIGIT4_INC,
    STATE_OPERATOR,
    STATE_OPERATOR_INC,
    STATE_YIELD,
    STATE_COMPUTE,
    STATE_ERROR,
    STATE_SHOW_ANSWER,
    STATE_SAVE_ANSWER
} State;

typedef enum {
    OP_ADD,
    OP_SUB,
    OP_MUL,
    OP_DIV,
    OP_COUNT
} Operator;

/* Status flags */
#define FLAG_OPERAND2   (1u << 0)   /* Set while entering operand 2 */

#define MAX_RESULT      9999

/* Input bit positions (used for edge detection) */
#define IN_SW1          (1u << 3)
#define IN_SW2          (1u << 2)
#define IN_SW3          (1u << 1)
#define IN_SW4          (1u << 0)
#define IN_ONBOARD      (1u << 4)

/* ---------------------------------------------------------------------------
 * FSM data
 * ------------------------------------------------------------------------- */

static State    current_state = STATE_INIT;
static uint8_t  flags;

static uint8_t  digits[4];          /* digits[0] = Digit1 (thousands) ... digits[3] = Digit4 (ones) */
static uint16_t operand1;
static uint16_t operand2;
static Operator op;
static int32_t  answer;
static uint16_t memory;             /* Last saved calculation */

static uint8_t  inputs_prev = 0xFF;  /* All inputs idle high (pull-ups) */

/* ---------------------------------------------------------------------------
 * Hardware stubs - fill in once pins are initialized
 * ------------------------------------------------------------------------- */

/* Returns the raw (debounced) level of each input as IN_* bits.
 * Inputs are pulled up: a released button reads 1, a pressed button reads 0. */
static uint8_t read_inputs(void)
{
    uint8_t inputs = ((GPIOF->IDR & 0x0780) >> 7);
    inputs |= ((~(GPIOI->IDR) & 0x0800) >> 7); // Shift 7 times to have the bit in position 4

    return inputs;
}

/* Shows a value on the 7-segment display */
static void display_value(uint16_t value)
{
    char str[5]; // 4 digits + null-terminator

    // Convert to 4 zero-padded digit characters, thousands first, so every
    // display position always gets a valid character
    str[0] = (char)('0' + (value / 1000) % 10);
    str[1] = (char)('0' + (value / 100) % 10);
    str[2] = (char)('0' + (value / 10) % 10);
    str[3] = (char)('0' + value % 10);
    str[4] = '\0';

    flashDisplay(str);
}

/* Shows the current operator on the 7-segment display */
static void display_operator(Operator o)
{
    (void)o;
    switch(o) {
    	case OP_ADD:
			flashDisplay("add");
    		break;
    	case OP_SUB:
			flashDisplay("sub");
			break;
    	case OP_MUL:
			flashDisplay("mul");
			break;
    	case OP_DIV:
			flashDisplay("div");
			break;
    	default:
    		flashDisplay("err");
    }
}

/* Shows an error indication on the 7-segment display */
static void display_error(void)
{
	flashDisplay("err");
}

/* ---------------------------------------------------------------------------
 * Helpers
 * ------------------------------------------------------------------------- */

static uint16_t digits_to_value(void)
{
    return (uint16_t)(digits[0] * 1000 + digits[1] * 100 + digits[2] * 10 + digits[3]);
}

static void clear_digits(void)
{
    for (int i = 0; i < 4; i++) {
        digits[i] = 0;
    }
}

static void increment_digit(uint8_t index)
{
    digits[index] = (uint8_t)((digits[index] + 1) % 10);
}

/* ---------------------------------------------------------------------------
 * FSM step - called once per main loop iteration
 * ------------------------------------------------------------------------- */

static void fsm_step(uint8_t falling)
{
    switch (current_state) {
    case STATE_INIT:
        /* TODO: any one-time setup */
        memory = 0;
        current_state = STATE_SELECT_OPERAND1;
        op = OP_ADD;
        break;

    case STATE_SELECT_OPERAND1:
        flags &= ~FLAG_OPERAND2;
        operand1 = 0;
        operand2 = 0;
        clear_digits();
        current_state = STATE_DIGIT1;
        break;

    case STATE_SELECT_OPERAND2:
        flags |= FLAG_OPERAND2;
        clear_digits();
        current_state = STATE_DIGIT1;
        break;

    /* ----- Digit entry (shared by operand 1 and operand 2) ----- */
    case STATE_DIGIT1:
        if (falling & IN_SW1)      current_state = STATE_DIGIT1_INC;
        else if (falling & IN_SW4) current_state = STATE_DIGIT2;
        break;

    case STATE_DIGIT1_INC:
        increment_digit(0);
        current_state = STATE_DIGIT1;
        break;

    case STATE_DIGIT2:
        if (falling & IN_SW1)      current_state = STATE_DIGIT2_INC;
        else if (falling & IN_SW4) current_state = STATE_DIGIT3;
        break;

    case STATE_DIGIT2_INC:
        increment_digit(1);
        current_state = STATE_DIGIT2;
        break;

    case STATE_DIGIT3:
        if (falling & IN_SW1)      current_state = STATE_DIGIT3_INC;
        else if (falling & IN_SW4) current_state = STATE_DIGIT4;
        break;

    case STATE_DIGIT3_INC:
        increment_digit(2);
        current_state = STATE_DIGIT3;
        break;

    case STATE_DIGIT4:
        if (falling & IN_SW1) {
            current_state = STATE_DIGIT4_INC;
        } else if (falling & IN_SW4) {
            if (flags & FLAG_OPERAND2) {
                /* Finished operand 2: wait for SW3 before computing */
                operand2 = digits_to_value();
                current_state = STATE_YIELD;
            } else {
                /* Finished operand 1 */
                operand1 = digits_to_value();
                current_state = STATE_OPERATOR;
            }
        }
        break;

    case STATE_DIGIT4_INC:
        increment_digit(3);
        current_state = STATE_DIGIT4;
        break;

    /* ----- Operator selection ----- */
    case STATE_OPERATOR:
        if (falling & IN_SW2)      current_state = STATE_OPERATOR_INC;
        else if (falling & IN_SW4) current_state = STATE_SELECT_OPERAND2;
        break;

    case STATE_OPERATOR_INC:
        op = (Operator)((op + 1) % OP_COUNT);
        current_state = STATE_OPERATOR;
        break;

    /* ----- Result ----- */
    case STATE_YIELD:
        if (falling & IN_SW3) current_state = STATE_COMPUTE;
        break;

    case STATE_COMPUTE:
        switch (op) {
        case OP_ADD: answer = (int32_t)operand1 + operand2; break;
        case OP_SUB: answer = (int32_t)operand1 - operand2; break;
        case OP_MUL: answer = (int32_t)operand1 * operand2; break;
        case OP_DIV:
            /* Divide by zero is an error: force the answer out of range */
            answer = (operand2 == 0) ? -1 : (int32_t)(operand1 / operand2);
            break;
        default: break;
        }
        current_state = (answer < 0 || answer > MAX_RESULT) ? STATE_ERROR : STATE_SHOW_ANSWER;
        break;

    case STATE_ERROR:
        if (falling & IN_SW4) current_state = STATE_SELECT_OPERAND1;
        break;

    case STATE_SHOW_ANSWER:
        if (falling & IN_SW4)          current_state = STATE_SELECT_OPERAND1;
        else if (falling & IN_ONBOARD) current_state = STATE_SAVE_ANSWER;
        break;

    case STATE_SAVE_ANSWER:
        memory = (uint16_t)answer;
        current_state = (falling & IN_SW4) ? STATE_SELECT_OPERAND1 : STATE_SHOW_ANSWER;
        break;

    default:
        current_state = STATE_INIT;
        break;
    }

}

/* Updates the 7-segment display based on the current state */
static void fsm_display(uint8_t level)
{
    /* For all states: onboard button held shows the last saved calculation.
     * Show Answer / Save Answer use the onboard button to save instead. */
    if (!(level & IN_ONBOARD) &&
        current_state != STATE_SHOW_ANSWER &&
        current_state != STATE_SAVE_ANSWER) {
        display_value(memory);
        return;
    }

    switch (current_state) {
    case STATE_DIGIT1: case STATE_DIGIT1_INC:
    case STATE_DIGIT2: case STATE_DIGIT2_INC:
    case STATE_DIGIT3: case STATE_DIGIT3_INC:
    case STATE_DIGIT4: case STATE_DIGIT4_INC:
        display_value(digits_to_value());
        break;

    case STATE_YIELD:
        display_value(operand2);
        break;

    case STATE_OPERATOR:
    case STATE_OPERATOR_INC:
        display_operator(op);
        break;

    case STATE_ERROR:
        display_error();
        break;

    case STATE_SHOW_ANSWER:
    case STATE_SAVE_ANSWER:
        display_value((uint16_t)answer);
        break;

    default:
        break;
    }
}

// How long each digit stays lit while scanning (roughly 2 ms at the 16 MHz default clock)
#define DIGIT_HOLD_DELAY 4000

/**
 * Shows a 4-character string by lighting one digit at a time. Each digit is
 * held for DIGIT_HOLD_DELAY, so this must be called repeatedly (e.g. every pass
 * of the main loop) for all four digits to appear lit at once.
 */
void flashDisplay(char *theString) {

	// Digit 1 (D10, PA8)
	GPIOA->ODR &= ~(0b1 << 8);                     // turn off all digits before changing segments
	GPIOB->ODR &= ~((0b1 << 14) | (0b1 << 15));
	GPIOI->ODR &= ~(0b1 << 1);
	flashSegment(theString[0]);
	GPIOA->ODR |= (0b1 << 8);
	simple_delay(DIGIT_HOLD_DELAY);

	// Digit 2 (D11, PB15)
	GPIOA->ODR &= ~(0b1 << 8);
	GPIOB->ODR &= ~((0b1 << 14) | (0b1 << 15));
	GPIOI->ODR &= ~(0b1 << 1);
	flashSegment(theString[1]);
	GPIOB->ODR |= (0b1 << 15);
	simple_delay(DIGIT_HOLD_DELAY);

	// Digit 3 (D12, PB14)
	GPIOA->ODR &= ~(0b1 << 8);
	GPIOB->ODR &= ~((0b1 << 14) | (0b1 << 15));
	GPIOI->ODR &= ~(0b1 << 1);
	flashSegment(theString[2]);
	GPIOB->ODR |= (0b1 << 14);
	simple_delay(DIGIT_HOLD_DELAY);

	// Digit 4 (D13, PI1)
	GPIOA->ODR &= ~(0b1 << 8);
	GPIOB->ODR &= ~((0b1 << 14) | (0b1 << 15));
	GPIOI->ODR &= ~(0b1 << 1);
	flashSegment(theString[3]);
	GPIOI->ODR |= (0b1 << 1);
	simple_delay(DIGIT_HOLD_DELAY);

	// Turn the last digit off so it isn't brighter than the others
	GPIOI->ODR &= ~(0b1 << 1);
}

/**
 * Drives segments A-G for one character. The segment codes from
 * translateCharacter() store segment A in bit 6 down to segment G in bit 0.
 */
void flashSegment(char theCharacter)
{
	int segmentCode = translateCharacter(theCharacter);

	// Assigns bit 6 in the 7-segment display sequence to Segment A (D2 on the board, PG6 on the processor)
	GPIOG->ODR = ((segmentCode >> 6) & 1) << 6;

	// Assigns bit 5 in the 7-segment display sequence to Segment B (D3 on the board, PB4 on the processor)
	GPIOB->ODR = ((segmentCode >> 5) & 1) << 4;

	// Assigns bit 4 in the 7-segment display sequence to Segment C (D4 on the board, PG7 on the processor)
	GPIOG->ODR |= ((segmentCode >> 4) & 1) << 7;

	// Assigns bit 3 in the 7-segment display sequence to Segment D (D5 on the board, PI0 on the processor)
	// Segments D, F, and G share port I, so only this first write uses '='
	GPIOI->ODR = ((segmentCode >> 3) & 1) << 0;

	// Assigns bit 2 in the 7-segment display sequence to Segment E (D6 on the board, PH6 in the processor)
	GPIOH->ODR = ((segmentCode >> 2) & 1) << 6;

	// Assigns bit 1 in the 7-segment display sequence to Segment F (D7 on the board, PI3 in the processor)
	GPIOI->ODR |= ((segmentCode >> 1) & 1) << 3;

	// Assigns bit 0 in the 7-segment display sequence to Segment G (D8 on the board, PI2 on the processor)
	GPIOI->ODR |= (segmentCode & 1) << 2;
}

/**
 * Takes a character and translates it into a set of bits that are used
 * for displaying on a sever-segment display.
 */
int translateCharacter(char theCharacter)
{
	int segmentCode;

	switch (theCharacter){
	case '0':
		segmentCode = 0b0000001;
		break;
	case '1':
		segmentCode = 0b1001111;
		break;
	case '2':
		segmentCode = 0b0010010;
		break;
	case '3':
		segmentCode = 0b0000110;
		break;
	case '4':
		segmentCode = 0b1001100;
		break;
	case '5':
		segmentCode = 0b0100100;
		break;
	case '6':
		segmentCode = 0b0100000;
		break;
	case '7':
		segmentCode = 0b0001101;
		break;
	case '8':
		segmentCode = 0b0000000;
		break;
	case '9':
		segmentCode = 0b0000100;
		break;
	case 'a':
		segmentCode = 0b0001000;
		break;
	case 'b':
		segmentCode = 0b1100000;
		break;
	case 'd':
		segmentCode = 0b1000010;
		break;
	case 'e':
		segmentCode = 0b0110000;
		break;
	case 'i':
		segmentCode = 0b1111001;
		break;
	case 'l':
		segmentCode = 0b1110001;
		break;
	case 'm':
		// 7-segment approximation of 'm': an 'n' with the top bar
		segmentCode = 0b0101010;
		break;
	case 'r':
		segmentCode = 0b1111010;
		break;
	case 's':
		segmentCode = 0b0100100;
		break;
	case 'u':
		segmentCode = 0b1000001;
		break;
	case 'v':
		segmentCode = 0b1010101;
		break;
	default:
		segmentCode = 255;
		break;
	}

	return segmentCode;
}

/*
 * Input pins are:
 *
 * A1 - SW1 - PF10
 * A2 - SW2 - PF9
 * A3 - SW3 - PF8
 * A4 - SW4 - PF7
 * B1 - B1 - PI11
 */
int main(void)
{
	// Initializing the clocks for ports A, B, G, H, I
	RCC->AHB1ENR |= 0b111000011;
	(void)RCC->AHB1ENR;   // read back so the clocks are running before GPIO access

	// Enable the clock for GPIO port F
	// In the AHB1ENR register, Bit 5 enables GPIOF
	RCC->AHB1ENR |= (1UL << 5);

	// Enable the clock for GPIO port I
	// In the AHB1ENR register, Bit 8 enables GPIOI
	RCC->AHB1ENR |= (1UL << 8);

	// Set pin PF10 as general purpose input
	GPIOF->MODER &= ~(3UL << (2*10));
	// Set pin PF9 as general purpose input
	GPIOF->MODER &= ~(3UL << (2*9));
	// Set pin PF8 as general purpose input
	GPIOF->MODER &= ~(3UL << (2*8));
	// Set pin PF7 as general purpose input
	GPIOF->MODER &= ~(3UL << (2*7));

	// Set pin PI11 as general purpose input
	GPIOI->MODER &= ~(3UL << (2*11));

	// Configure PF10 to be Pull-up using GPIO_PUPDR
	GPIOF->PUPDR |= (1UL << (2*10)); //PUPDR = Pull Up Pull Down Register
	// Configure PF9 to be Pull-up using GPIO_PUPDR
	GPIOF->PUPDR |= (1UL << (2*9)); //PUPDR = Pull Up Pull Down Register
	// Configure PF8 to be Pull-up using GPIO_PUPDR
	GPIOF->PUPDR |= (1UL << (2*8)); //PUPDR = Pull Up Pull Down Register
	// Configure PF7 to be Pull-up using GPIO_PUPDR
	GPIOF->PUPDR |= (1UL << (2*7)); //PUPDR = Pull Up Pull Down Register

	// Each pin only clears its own MODER/OTYPER bits so the SWD debug
	// pins (PA13, PA14) and PB3 keep their settings.

	// Initialization for 7-segment display pins (D2-D8 = A-G)

	// Initializes D2 (PG6, segment A) as push-pull output
	GPIOG->MODER  &= ~(3UL << (2 * 6));
	GPIOG->MODER  |=  (1UL << (2 * 6));
	GPIOG->OTYPER &= ~(1UL << 6);

	// Initializes D3 (PB4, segment B) as push-pull output
	GPIOB->MODER  &= ~(3UL << (2 * 4));
	GPIOB->MODER  |=  (1UL << (2 * 4));
	GPIOB->OTYPER &= ~(1UL << 4);

	// Initializes D4 (PG7, segment C) as push-pull output
	GPIOG->MODER  &= ~(3UL << (2 * 7));
	GPIOG->MODER  |=  (1UL << (2 * 7));
	GPIOG->OTYPER &= ~(1UL << 7);

	// Initializes D5 (PI0, segment D) as push-pull output
	GPIOI->MODER  &= ~(3UL << (2 * 0));
	GPIOI->MODER  |=  (1UL << (2 * 0));
	GPIOI->OTYPER &= ~(1UL << 0);

	// Initializes D6 (PH6, segment E) as push-pull output
	GPIOH->MODER  &= ~(3UL << (2 * 6));
	GPIOH->MODER  |=  (1UL << (2 * 6));
	GPIOH->OTYPER &= ~(1UL << 6);

	// Initializes D7 (PI3, segment F) as push-pull output
	GPIOI->MODER  &= ~(3UL << (2 * 3));
	GPIOI->MODER  |=  (1UL << (2 * 3));
	GPIOI->OTYPER &= ~(1UL << 3);

	// Initializes D8 (PI2, segment G) as push-pull output
	GPIOI->MODER  &= ~(3UL << (2 * 2));
	GPIOI->MODER  |=  (1UL << (2 * 2));
	GPIOI->OTYPER &= ~(1UL << 2);

	// Initialization for digit selection (D10-D13)

	// Initializes D10 (PA8) as push-pull output
	GPIOA->MODER  &= ~(3UL << (2 * 8));
	GPIOA->MODER  |=  (1UL << (2 * 8));
	GPIOA->OTYPER &= ~(1UL << 8);

	// Initializes D11 (PB15) as push-pull output
	GPIOB->MODER  &= ~(3UL << (2 * 15));
	GPIOB->MODER  |=  (1UL << (2 * 15));
	GPIOB->OTYPER &= ~(1UL << 15);

	// Initializes D12 (PB14) as push-pull output
	GPIOB->MODER  &= ~(3UL << (2 * 14));
	GPIOB->MODER  |=  (1UL << (2 * 14));
	GPIOB->OTYPER &= ~(1UL << 14);

	// Initializes D13 (PI1) as push-pull output
	GPIOI->MODER  &= ~(3UL << (2 * 1));
	GPIOI->MODER  |=  (1UL << (2 * 1));
	GPIOI->OTYPER &= ~(1UL << 1);

    for (;;) {
        uint8_t level  = read_inputs();
        uint8_t falling = ~level & inputs_prev;
        inputs_prev = level;

        fsm_step(falling);
        fsm_display(level);
    }
}

void simple_delay(uint32_t count) {
    while (count--) {
        __asm__("NOP");
    }
}
